quests[33136] = { id = 33136, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Rainy Day is Here", objectives = "{name}, I can see the look in your eyes.  I have heard of your deeds in the tournament.  You are ready to choose a companion!\n\nThis one time I will gift you these two additional coins.  Use them wisely, as you will only be able to earn one coin each week from this point forward.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33137] = { id = 33137, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Celestial Tournament", description = "The Timeless Isle is home to a special tournament created to test the leadership of its participants.  Those who prove their worth are granted an opportunity to befriend an embodiment of virtue - the progeny of the celestials themselves.\n\nEach time you win the tournament, I will honor you with a single ceremonial coin.  When you have enough coins, speak with me again to further discuss your reward.", progress = "You must win the Celestial Tournament to receive your coin.", completion = "A true leader stands before me.  It is my honor to grant you this coin, {name}.", objectives = "Speak with Master Li to enter the Celestial Tournament and defeat all the challengers there.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33138] = { id = 33138, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Why Do We Fight?", description = "Oh my friend, today you and your companions have put an end to the sha that has plagued Pandaria since before time was recorded. You have accomplished that which even the titans and their mogu servants could not: destroying the last breaths of Y'Shaarj.\n\nCome, will you join me in the Vale of Eternal Blossoms? There is something I would like you to bear witness to.", completion = "Our precious Vale of Eternal Blossoms. So much destruction and violence. But... I sense a glimmer of hope.", objectives = "Lorewalker Cho wishes to speak with you in the Vale of Eternal Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33139] = { id = 33139, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secrets Lost, Forever?", description = "<With the ancient Lin family noodle soup recipe in hand, you decide to set out for the Halfhill Market.>\n\n<If anyone in Pandaria knows how to decipher this scroll, it's Sungshin Ironpaw.>", sourceObjective = "Speak with Sungshin Ironpaw at the Halfhill Market in the Valley of the Four Winds.", sourceObjectiveStatus = "unverified-source-field" }
quests[33145] = { id = 33145, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grimfrost Hill", description = "Free the Frostwolves being held by the Grimfrost ogres." }
quests[33146] = { id = 33146, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noodle Time", description = "Hello, {name}. Care to work the noodle stand again?\n\nJust let me know when you're ready to work another shift and I'll get everything set up.", completion = "Great work {name}! Everyone always loves it when they hear that you'll be making noodle soup. People come from all over Pandaria just to try a taste.", objectives = "Queue for and complete a shift at the Halfhill noodle stand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33147] = { id = 33147, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Last Gasp of Y'Shaarj", description = "A dark, vaporous substance stains the floor of the room. This is all that remains of the Old God Y'Shaarj.", completion = "Do you see? Even now it fades from being.", objectives = "Speak with Lorewalker Cho in the Siege of Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33148] = { id = 33148, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Missing Hunting Party", description = "xxxxxxx" }
quests[33149] = { id = 33149, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blackrock Down", description = "Hey {name}, just the {race} I was hopin' to see. I just received a distress call from Thaelin.\n\nHe and Romuul left a while ago to do some reconnaissance on another one of those draenei crystals, but now it sounds like they're in wee a spot o' trouble.\n\nKnowing Thaelin, he's going to need some help.", sourceObjective = "Locate Thaelin Darkanvil outside of Gar'mak Quarry.", sourceObjectiveStatus = "unverified-source-field" }
quests[33150] = { id = 33150, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brute Beatdown", description = "This Iron Horde has no honor.\n\nTheir leaders spit on us and laugh as we do their bidding.\n\nMany of my brothers and sisters have died at their hands.\n\nIt is time to send these savages to an early grave.", objectives = "Kill Mokrik Blackfingers, Rukah the Machinist, and Gar Steelcrush.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33151] = { id = 33151, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Saw Scout Valdez Arrive" }
quests[33154] = { id = 33154, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fight for Freedom", description = "The Iron Horde keeps us here against our will. They control us with fear and aggression.\n\nIt pains me to see my people subjugated like this.\n\nAll we need to stand up to these beasts is hope... and a large weapon.", objectives = "Give weapons to Enslaved Draenei and kill Iron Horde orcs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33155] = { id = 33155, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Task: Destroy Iron Horde Banners" }
quests[33156] = { id = 33156, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Time Keeper Kairoz", description = "You have found your way to the Timeless Isle, {class}. The bronze dragonflight is keen to investigate the mysteries of this place, but the island is dangerous, and we will need your help.\n\nMidway down this beach, you will find a paved path to the east.\n\nIt will lead you to the ancient Celestial Court. You will find Kairoz there, one of the Keepers of Time that we are working with.\n\nKairoz will answer any questions you might have. Be careful: The way may not be safe.", completion = "Ah! Well met, {name}!\n\nI was told you would be coming, but had not expected you so soon.\n\n...or has it been a long while? It is difficult to tell, here.\n\nSo! Shall we begin?", objectives = "Speak with Kairoz on the Timeless Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33157] = { id = 33157, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadowmoon Phased Terrain Swap 1" }
quests[33158] = { id = 33158, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadowmoon Phased Terrain Swap 2" }
quests[33159] = { id = 33159, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadowmoon Phased Terrain Swap 3" }
quests[33160] = { id = 33160, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Time Keeper Kairoz", description = "You have found your way to the Timeless Isle, {class}. The bronze dragonflight is keen to investigate the mysteries of this place, but the island is dangerous, and we will need your help.\n\nMidway up this beach, you will find a paved path to the east.\n\nIt will lead you to the ancient Celestial Court. You will find Kairoz there, one of the Keepers of Time that we are working with.\n\nKairoz will answer any questions you might have. Be careful: The way may not be safe.", completion = "Ah! Well met, {name}!\n\nI was told you would be coming, but had not expected you so soon.\n\n...or has it been a long while? It is difficult to tell, here.\n\nSo! Shall we begin?", objectives = "Speak with Kairoz on the Timeless Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33161] = { id = 33161, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Timeless Tour", description = "You should first familiarize yourself with the island.\n\nExplore. Investigate anything that catches your interest. Return when you're done, and I'll reward you for whatever information you've gathered about this strange place.\n\nAnd do be careful! Monstrous beasts and supernatural creatures abound.", completion = "Bizarre place, is it not?\n\nI do hope you found some adventure along the way.", objectives = "Explore the Timeless Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
