quests[33168] = { id = 33168, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heart On Fire", description = "We have the shards, but now they must be combined. There's a forge here, but even its fires aren't hot enough for our purposes.\n\nHowever, there is a demon nearby that burns hot as the sun.\n\nGul'dan, or perhaps Razuun, has managed to summon an infernal. The thing calls itself Krosnis, which means \"furnace.\"\n\nThe demon's heart burns hotly enough. All you need do is collect it.", progress = "With the combined might of the shards, we should be able to trap Gul'dan.", completion = "Quickly, place the heart in the forge. We'll use its infernal heat to forge the trap.", objectives = "Collect the Fiery Heart from Krosnis.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
