quests[33210] = { id = 33210, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One-Time Chest - Blazing Chest" }
quests[33211] = { id = 33211, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Timeless Question", description = "Destiny. Fate. Karma. Words like these imply that the timeways are unassailable.\n\nWould that were the case. To this day, many of Azeroth's inhabitants yearn to change the past. Yet just as our experiences shape us, they also shape the world around us.\n\nConsider how those threads have woven the fabric of today's reality. Cut enough threads, and causation inevitably fails, unraveling that fabric. Indeed, cutting even a single thread short can result in disaster, provided it is the right thread.", progress = "Let us speak, then, of events that have already come to pass.", completion = "This is the great burden of the Historian - should Azeroth's timeways come under attack, we must reconstruct history exactly as it happened, or the consequences could be dire. As we spread our stories and knowledge, so do we create a stronger future for us all.", objectives = "Correctly answer one of Evelyna's questions about the history of Azeroth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33216] = { id = 33216, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One-Time Chest - T1G1" }
