quests[33222] = { id = 33222, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Little Tommy Newcomer", description = "I've got a battle pet, too! Want to battle? It'll be fun, I promise!", progress = "I'm ready to battle!", completion = "You cheated! I know it!", objectives = "Defeat Little Tommy Newcomer in a pet battle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
