quests[33227] = { id = 33227, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One-Time Chest 028" }
quests[33228] = { id = 33228, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Time In Your Hands", description = "Inhabitants of this strange island barter with a special currency, immune from the fickle fluctuations of time.\n\nYou would do well to gather as many of these \"timeless coins\" as possible! They can be found hidden away in small caches, or gathered from creatures all around the island. Larger, rarer creatures are a better source of coins - you may find it profitable to venture forth as part of a group.\n\nIntroduce yourself to Mistweavers Ai and Ku across the Celestial Court, and gather some coins for me.", progress = "You're back already? It feels like we spoke only moments ago.", completion = "I believe you are getting the feel for this place! Yes, opportunities abound to gather up timeless treasures. Strange events happen all the time here - always keep your eyes open.\n\nSpeak to the mistweavers you met to spend your hard-earned currency. Meanwhile, I will continue my research.\n\nHere is a taste of some of the treasures you can find here. More powerful items are available. You'll find that hidden caches in the more dangerous parts of the island can be... extremely rewarding. Good luck.", objectives = "Gather 1000 Timeless Coins and introduce yourself to Mistweaver Ai and Mistweaver Ku.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33229] = { id = 33229, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Flash of Bronze...", description = "As you survey the devastation of the vale, a flash of bronze catches your eye. Unless you're mistaken, a tiny gnome is trying to catch your attention from the balcony above Mogu'shan Palace, just outside of the Seat of Knowledge.\n\nYou should see what she wants.", completion = "<The tiny gnome's eyes reflect the light with a copper sheen. She is not what she seems.>\n\n{name}! I have been waiting for you. The bronze dragonflight has need of your services.", objectives = "Speak with Chromie outside of the Seat of Knowledge in the Vale of Eternal Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33230] = { id = 33230, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Flash of Bronze...", description = "As you survey the devastation of the vale, a flash of bronze catches your eye. Unless you're mistaken, a tiny gnome is trying to catch your attention from the balcony above Mogu'shan Palace, just outside of the Seat of Knowledge.\n\nYou should see what she wants.", completion = "<The tiny gnome's eyes reflect the light with a copper sheen. She is not what she seems.>\n\n{name}! I have been waiting for you. The bronze dragonflight has need of your services.", objectives = "Speak with Chromie outside of the Seat of Knowledge in the Vale of Eternal Blossoms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33231] = { id = 33231, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Journey to the Timeless Isle", description = "The bronze dragonflight has discovered a most unusual pandaren phenomenon, {class}. Emerging from the mists, far off the coast of the Jade Forest - an island that was lost in time!\n\nIt is a dangerous place, perhaps the most perilous in all of Pandaria. But we are determined to unravel its mysteries.\n\nHere, take this timepiece. A single click will whisk you to the island. Get yourself established, and speak with Watcher Lara. She will guide you to our chief investigator.", completion = "I see Chronormu has made good on her promise! You are right on time.", objectives = "Speak with Watcher Lara on the Timeless Isle, off the coast of the Jade Forest.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33232] = { id = 33232, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Journey to the Timeless Isle", description = "The bronze dragonflight has discovered a most unusual pandaren phenomenon, {class}. Emerging from the mists, far off the coast of the Jade Forest - an island that was lost in time!\n\nIt is a dangerous place, perhaps the most perilous in all of Pandaria. But we are determined to unravel its mysteries.\n\nHere, take this timepiece. A single click will whisk you to the island. Get yourself established, and speak with Watcher Alundra. She will guide you to our chief investigator.", completion = "I see Chronormu has made good on her promise! You are right on time.", objectives = "Speak with Watcher Alundra on the Timeless Isle, off the coast of the Jade Forest.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33233] = { id = 33233, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Short-Supply Reward" }
quests[33234] = { id = 33234, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meaty Crane Leg", progress = "What do you have there?", completion = "Oh wow, that thing is really meaty! Think of the soup I could make with it! Here, I will give you some timeless coins for it." }
quests[33235] = { id = 33235, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Great Turtle Meat", progress = "Well that smells... interesting...", completion = "It is so... spongy! Hmm, yes, perhaps a little soy sauce and some oil... Here, take these coins as payment!" }
quests[33236] = { id = 33236, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heavy Yak Flank", progress = "What smells like bloody flank?", completion = "Thanks for the flanks! Ha ha, just a little food humor for you. Here are some coins for not groaning!" }
quests[33238] = { id = 33238, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thick Tiger Haunch", progress = "I have a 'haunch' you have something for me!", completion = "The stripes on this haunch are so interesting, I wonder how they will cook? First I am going to have to tenderize it a bit, though. Time to beat some meat! Here is a little something for your troubles!" }
quests[33239] = { id = 33239, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pristine Firestorm Egg", progress = "What is that heavenly smell?", completion = "I have never seen one of those before, where in the world did you get it? It is so beautiful, I am not sure I can bear to break it open. Just kidding, this is going to make the best omelet! Here is a bunch of coins!" }
quests[33248] = { id = 33248, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proving Grounds", description = "You there! It's {name}, right? Greetings. I'm Taijing.\n\n<Taijing sizes you up.>\n\nYou look strong. I've seen you a few times here in the Vale, but I've never seen you fight before. I wonder... are you as strong as you seem?\n\nIf you're interested in proving yourself, speak with Trial Master Rotun at the Temple of the White Tiger, in Kun-Lai. He will put you to the test.", completion = "Welcome to the Proving Grounds, {class}. I am Trial Master Rotun.\n\nHere, you may test your skill at performing several different combat roles: dealing damage, absorbing damage, and healing. I shall administer and judge these trials.\n\n\n\nAre you ready to begin?", objectives = "Speak with Trial Master Rotun at the Temple of the White Tiger, then enter the Proving Grounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33249] = { id = 33249, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proving Grounds", description = "You there! It's {name}, right? Greetings. I'm Jinho.\n\n<Jinho sizes you up.>\n\nYou look strong. I've seen you a few times here in the Vale, but I've never seen you fight before. I wonder... are you as strong as you seem?\n\nIf you're interested in proving yourself, speak with Trial Master Rotun at the Temple of the White Tiger, in Kun-Lai. He will put you to the test.", completion = "Welcome to the Proving Grounds, {class}. I am Trial Master Rotun.\n\nHere, you may test your skill at performing several different combat roles: dealing damage, absorbing damage, and healing. I shall administer and judge these trials.\n\n\n\nAre you ready to begin?", objectives = "Speak with Trial Master Rotun at the Temple of the White Tiger, then enter the Proving Grounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33250] = { id = 33250, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Time-Lost Treasure", progress = "Oh my, what is THAT?", completion = "This is astounding, an egg like this hasn't been seen on Pandaria for thousands of years. I believe some of our more ancient scrolls will detail how best to handle it, though many are written in Mogu. I had best get to translating, then!" }
quests[33252] = { id = 33252, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Winter Veil Gift", objectives = "A small tag on this present reads:\n\nHappy holidays, {name}!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33253] = { id = 33253, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the Defense of Karabor", description = "Get your bad self to Karabor, you {class}y little {race}-muffin.", sourceObjective = "Speak with [FLIGHT MASTER], then report to Akama at the rear entrance to Karabor.", sourceObjectiveStatus = "unverified-source-field" }
quests[33255] = { id = 33255, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Righteous March", description = "The Iron Horde have overtaken Karabor. If we don't act now, we will lose the city.\n\nExarch Akama and the last of our forces are trapped within the city, but your garrison forces are still outside the temple, awaiting your orders.\n\nCome and fly with me. We will meet your forces on the field. With the naaru by our side, we will make one last charge to retake the city!", completion = "Now, to destroy these orcs once and for all.", objectives = "Escort your garrison forces to the Temple of Karabor by slaying all the orcs in the Path of Light.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33256] = { id = 33256, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Defense of Karabor", description = "Defend Karabor from the Iron Horde.\n\nAt the end of the northern courtyard is Arnokk the Burner. He guards the entrance to the harbor behind Karabor, where the main Iron Horde army is waiting.\n\nOnce we've taken care of him, we'll need to deal with the Iron Horde leader, Commander Vorka.", completion = "We did it, {name}. Without your heroic efforts, the Temple of Karabor would have been lost to the Iron Horde.\n\nProphet Velen would be proud of us.", objectives = "Destroy the Iron Horde in Karabor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33257] = { id = 33257, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sprite Fright - Tracking Quest" }
