quests[33260] = { id = 33260, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest - First - Gu'chi the Swarmbringer" }
quests[33261] = { id = 33261, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest - First - Emerald Gander" }
quests[33263] = { id = 33263, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gloomshade Grove", description = "<This looks like one of the pack mules from your garrison. It's strange that it's wandering out here alone.\n\nYou probably should investigate.>", progress = "<The mule looks frightened.>", completion = "Thank the Light. <Cough> I didn't think I would get out of here alive.", objectives = "Search Gloomshade Grove for clues.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33264] = { id = 33264, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Proper Burial", description = "<The orc is visibly winded. A large pool of blood is gathering at his feet.>\n\nWe were out hunting when we found the wolves under attack.\n\nMany ogres were slaughtered by our blades... but their numbers were too great.\n\nI'm going to catch my breath before I go out and kill the rest of them.\n\nHere, take this torch. Go give my brothers and sister a proper burial and return to me.", objectives = "Burn the corpses of dead Frostwolf Outriders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33265] = { id = 33265, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Friendly Foreling", description = "You saved us! You my best friend.\n\n<The forling gives you a big hug.>\n\nYou so nice best friend. You smell so good. The other friends eat your friends. So sad. They are so not good friends.\n\nI know where more friends are! You need friends? My friends take my things. I need things back before I can be chief. Things make me strong.\n\n<The foreling looks at you longingly. Then it sniffs you>\n\nFollow me best friend, we find all the friends, and all the things.", objectives = "Help the friendly foreling gather some things before meeting with the chief.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33266] = { id = 33266, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Light in the Dark - Tracking Quest" }
quests[33268] = { id = 33268, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Collect Moonstones", description = "We need moonstones. Foreling friends LOVE moonstones. moonstones best gift since foods. Foods soooo good. Best friend loves foods? Of course best friend loves foods.\n\nIf we have all the moonstones, foreling friends love us, maybe give us ALL the foods. Maybe if we have so many moonstones foreling friends make me chief. Imagine...\n\n<The forling looks into the woods and smacks it's lips.>\n\nWe find all the moonstones.", objectives = "Collect 12 moonstones to help the friendly foreling gain more friends.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33269] = { id = 33269, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cleaning Up Gul'var", description = "Khadgar wants you to concentrate on Gul'dan, but that doesn't mean we're not going to take down the Shadow Council in the process.\n\nGul'var's filthy with Shadow Council villains. Let's do something about them.", completion = "Every world is better off without those demon-loving scum.", objectives = "Kill 20 Shadow Council orcs at Gul'var.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33270] = { id = 33270, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest - First - Ironfur Steelhorn" }
quests[33271] = { id = 33271, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Game of Thorns", description = "<Jarrod is clearly injured. He winces in pain as he begins to talk.>\n\nMy lead forest operator, Shelly... she is being held not far from here...", completion = "<Something is moving under all of these roots.>", objectives = "Kill King Deathbloom.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
