quests[33320] = { id = 33320, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Two Birds, One Power Core", description = "The power core is of the utmost importance, {name}. We need to locate it as quickly as possible. Those Iron Horde scum carted it away hours ago though. It could be anywhere!\n\nI think we should start with the leadership here and work our way down. I'm sure we're bound to find some clues and we'll be setting them back at the same time." }
