quests[33323] = { id = 33323, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Finale - Tracking Quest" }
quests[33327] = { id = 33327, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "This One Is Just Right", description = "I noticed the commanders carrying around what appeared to be journals. I have a feeling we'll get more than enough information from those, if we can get our hands on them anyway.\n\nThe journals are never far away from their owners so this could be tricky...", objectives = "Retrieve Mokrik's Tattered Journal, Rukah's Dusty Journal, and Gar's Well-Kept Journal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33330] = { id = 33330, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Task: Trapped Critters", description = "Free the Frostwolves being held by the Grimfrost ogres." }
quests[33331] = { id = 33331, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Captured Critters", description = "This poor critter is about to be podling food. It would be pretty easy to set this little guy free.", objectives = "Free Captured Critters in Gloomshade Grove.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33332] = { id = 33332, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hints From The Past", description = "There is much to learn of this place, yet it does not yield its secrets willingly.\n\nSomething you mentioned the last time that we spoke intrigues me. This Mistweaver Ai, she carries a time-worn journal, if I recall? This may be the answer to many of our questions, or it may simply raise more. I suppose that it all depends on the diligence of the explorer that put pen to paper in this preposterous place.\n\nObtain a time-worn journal and return to me with it. We shall delve into its mysteries together.", progress = "Ah, you have returned. Do you have the journal?", completion = "Ah, you have it! Excellent!\n\nA cursory glance indicates that my presumptions were not far-fetched. Though the pages are worn and waterlogged, most of the entries are still legible. It appears that our friend, explorer Harrington, was quite verbose in cataloguing the creatures and treasures he found on his journey through the island.\n\nWell, are you simply going to stand there? This tome is a veritable trove of mysteries, and we have barely scratched the surface! Adventure awaits!", objectives = "Purchase a Time-Worn Journal from Mistweaver Ai.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33333] = { id = 33333, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Timeless Treasures", description = "The journal indicates that treasures abound across the island, sometimes temptingly out of reach, and other times hidden in dark caves and hollows. What might have been secreted away here, many generations ago?\n\nAnd perhaps more importantly, by whom?\n\nSearch the island for such treasures, and return to me with your findings. Be warned that all that glitters is not gold, yet the reverse is also true. Sometimes the simple hollowed-out stump is the best hiding place for one's valuables.", progress = "Time flows oddly in this place, I cannot tell if I should be sleeping or eating my mid-day meal.", completion = "I am happy that you have discovered some riches for your efforts, though we are no closer to unraveling this mystery than before. Take solace in the knowledge that many such bounties are surely scattered throughout the island, eagerly awaiting your exploration skills and combat prowess.\n\nOh, one last thing, my young adventurer - do not forget to look to the skies now and again.", objectives = "Find a hidden treasure on the Timeless Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33334] = { id = 33334, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Strong Enough To Survive", description = "An island lost in time and yet it returns flourishing with life!\n\nWhere did this island travel to? Did it simply hop forward in time, or did it languish in the dark reaches of the Twisting Nether?\n\nThere is one thing for certain: the creatures that inhabit this place are far more than they seem. I sense a hidden power in them, forged by the eons. Seek out the champions of their species, duly marked by their power and prowess, and vanquish five such creatures.\n\nIn death, we may find the clues we seek.", progress = "This journal really is fascinating, I wonder what happened to our dear explorer friend in the end.", completion = "An interesting story of combat and bravery, though I fear that we learned little from your endeavors save that you are quite the adventurer. It seems that we find ourselves at an impasse with each twist and turn of this tale. Time is a fickle mistress.\n\nYou may wish to spend some time honing your skills here, before the sun sets.", objectives = "Defeat five Rare or Rare Elite creatures on the Timeless Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33335] = { id = 33335, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Last Emperor", description = "From what I have gathered, this place used to be a tournament ground of sorts, where warriors from throughout Pandaria would show their prowess by following in the footsteps of their last emperor, Shaohao.\n\nI have heard that when Shaohao completed his trials, he became one with the land, and enveloped Pandaria in a thick mist, obscuring it from even our abilities to penetrate the passages of time.\n\nThat sounds quite interesting, perhaps you should speak with him?", progress = "Greetings, I am Shaohao. Are you here to hear the wisdom of the celestials?", completion = "In my pride, I sought to keep Pandaria a secret, and once again I have found myself learning great lessons from this land. I am glad to be able to share my stories with my people, once again, in that they may learn as I have, and learn from my mistakes. Perhaps you, too, can still learn a thing or two from the lessons of Pandaria.", objectives = "Speak with Emperor Shaohao.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33336] = { id = 33336, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Essence of Time", description = "It is about time that I revealed to you my purpose on this island.\n\nThe bronze dragonflight's powers have diminished greatly - we can now only catch furtive glimpses through time. It is... quite frustrating.\n\nBut we are not entirely without means. I hold in my hand the Vision of Time, an artifact of my own creation. The creatures of this isle have passed through time, and may carry with them some of its essence. With it, we will fill the hourglass, granting us a window into the timeways once more.", progress = "Have you found anything?", completion = "Epoch stones are quite rare. The crystallized essence of time, they require a rapid passage through the ages to form. Their presence here indicates that the island may not exist in one time at all, but shift rapidly from timeway to timeway.\n\nThat is of little importance at the moment, though. There are important moments in time that require our attention. Give me a moment to grind the stone and add it to the Vision of Time hourglass.", objectives = "Obtain an Epoch Stone from one of the creatures on the Timeless Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33337] = { id = 33337, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Vision in Time", description = "Look at how the Vision reacts! Astounding! Even now it shows shadows of timeways that flit around us constantly. Though not true sands of the Hourglass of Time, the finely-ground epoch stones certainly have a power all their own. Our first task is to use them to calibrate the Vision of Time.\n\nTake the Vision of Time to a location where history is in the making: the Siege of Orgrimmar. Once there, turn the hourglass and see what happens.", progress = "Did you use the Vision of Time? What was the result?", completion = "How very intriguing. I will have to make some additional modifications, and perhaps locate a more proper catalyst. Thank you for performing this experiment, I trust that you did not experience any adverse effects? Should you feel up to the task, I may have use of your services again shortly.", objectives = "Use the Vision of Time in the Siege of Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33338] = { id = 33338, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Empowering the Hourglass", description = "The hourglass gives us glimpses into the streams of time we once walked as easily as a well-worn path.\n\nGather additional epoch stones, so that we may continue to use the power of the hourglass to delve into the mysteries of the timeways.\n\nThe future depends on it.", progress = "Epoch stones are rare, crystallized temporal essence.", completion = "Give me a moment to grind the stones and add them to the hourglass, and we shall see what new events unfold.\n\nIt's really quite convenient, I've a particular affinity for specific moments, rather than lengthy chains of events.\n\nThe timeways tell me that we will have need of its power many times in the near future.", objectives = "Collect Epoch Stones from creatures on the Timeless Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33340] = { id = 33340, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Timeless Nutriment", description = "As you have surmised, the flora and fauna of this island are quite unusual. Not all explanations are mysterious, however. Sometimes, we must listen to the land, to hear the tales of the world around us. Have you considered that the creatures of this island grew to such proportions simply from the nutriment of the land you walk upon?\n\nYou will find nutriment in abundance throughout the island: ripe fruits, eggs, meat, flowers, nuts, and even the stones themselves. Eat, and discover the power of the land.", progress = "Have you enjoyed the abundance of the island?", completion = "The island gives in abundance, in nutriment and in answers. You only need look around to find what you seek.", objectives = "Consume a Ripe Crispfruit, Sand-Covered Egg, Charged Crystal, Huge Yak Roast, Roasted Seed, or Fire Poppy on the Timeless Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33341] = { id = 33341, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wayshrines Of The Celestials", description = "Many years ago, these grounds were a place where my people would come in pilgrimage. Here, they would listen to the words of the celestials, and meditate for many days. In their meditations, they found the fear, anger, despair, doubt, and violence that plagued their spirits.\n\nBefore them would be a pathway to enlightenment. For each, the pathway would be different. For all of them, the pathway began with wisdom.\n\nTravel the island, as they did, and discover one of the lost wayshrines of the celestials.", progress = "The shrines will not always avail themselves to you. Do not give up, such is the test of patience.", completion = "You have experienced the power and wisdom of the Celestials. Let it flow through you now, and remain in your heart for all time.", objectives = "Find an active Time-Lost Shrine and request a blessing from the celestials.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33342] = { id = 33342, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drive Back The Flame", description = "The pandaren once existed in harmony with the Ordon yaungol. When the island suddenly disappeared, the Ordon faced certain death. In their desperation, the chief shaman called out for aid to the Fire Lords, and was answered.\n\nOrdos was his name. Now, he is a creature of anger and violence. Though his people were saved, he burns endlessly in molten agony.\n\nThere is harmony no longer. The Ordon seek to take the Celestial Court, and sacrifice us all to Ordos. Drive them back, and restore balance.", progress = "The Ordon are not to be trifled with. They have survived on this island under the protections of their ever-burning demigod, Ordos.", completion = "Your accomplishments are many, and your bravery cannot be questioned. The Ordon have been driven back for the moment, but do not underestimate them. To restore harmony to the isle, we must continue to be vigilant.", objectives = "Earn an Honored Reputation with Shaohao by defeating yaungol forces on the Timeless Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33343] = { id = 33343, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Archiereus Of Flame", description = "Your efforts have driven back the Ordon and brought peace to the Celestial Court, but it will not last. It is time to silence the great emissary of Ordos - the Archiereus of Flame.\n\nSpeak with Mistweaver Ku and purchase a scroll of challenge, then travel to Three-Breeze Terrace to the north. Issue a challenge at the challenge stone, it will undoubtedly catch the attention of the Ordon, drawing the archiereus out of the Ordon Sanctuary. It is your only chance.", progress = "The emissaries of Ordos are powerful, do not underestimate them.", completion = "The emissaries of Ordos have been silenced, for a time.\n\nKnow that anger, violence, and hatred will never cease. Wherever there is the darkness within one's spirit, you will find these sha awaiting you. They may become manifest in many forms: a warlord hungering for power, a dagger in your back in the night, a young prince following a dark path, and even your own battle against forces not aligned with your own.\n\nLearn from the lessons of these emotions, lest you lose yourself to the darkness.", objectives = "Summon and defeat the Archiereus of Flame.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33344] = { id = 33344, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Armed and Dangerous", description = "Ligra was sent with extra weapons to equip enslaved Frostwolves.\n\nArm the Frostwolf Slaves so they can cut their way from their slavers.", completion = "The ogres appear to be in disarray and many of my people are now free.", objectives = "Give weapons to 10 Frostwolf Slaves.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33345] = { id = 33345, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Shaman Weekly Attempt" }
