quests[33348] = { id = 33348, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "\"Tom\" Bone Apart - Intro Tracking Quest" }
quests[33349] = { id = 33349, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "STARTER QUEST - RED->PURPLE 15", description = "BFor this challenge, run through the arch, then get to the RED marker, the PURPLE marker, then return here before the bell tolls 15 times. Good luck!", objectives = "Run through the arch, hit the red marker, then the purple marker, then return to the Ironelf games camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33350] = { id = 33350, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Redridge Group Trial", description = "Redridge group trial. Get to the blue marker, then the green marker, then the red marker, then return to the Lakeshire Ironelf cmap.", objectives = "Log description text.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33351] = { id = 33351, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Become Chief", description = "xxxxxxx", objectives = "Kill the Foreling Chief.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33352] = { id = 33352, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Event: Chief killed", description = "Okay best friend. Let's talk to old smelly mud chief. We smell so good like moonstone and foods. We give friends moonstones. We tell friends I'm chief. We get ALL the foods.\n\nStupid bad smelling chief. Thinks I'm foods? Pshh. He's foods.\n\nTime for foods best friend.", sourceObjective = "Kill the Foreling Chief.", sourceObjectiveStatus = "unverified-source-field" }
quests[33354] = { id = 33354, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Mother's Demise", description = "This is the pelt of Darkmoon Island's monstrous den mother.\n\nYebb Neblegear, beastmaster of the Darkmoon Faire, will be happy to know the ghostly wolf and her spawn will no longer be terrorizing his menagerie... at least for a little while. Bring it to him.", progress = "Is that what I think it is?", completion = "At last, that vicious beast has been slain! Thank you.", objectives = "Bring Moonfang's Pelt to Yebb Neblegear at the Darkmoon Faire on Darkmoon Island.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33358] = { id = 33358, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noodle Time: Bonus", description = "Hello, {name}. Think you're a truly extraordinary noodle chef?\n\nLet's see what you've got!", completion = "Excellent work {name}! Everyone always loves it when they hear that you'll be making noodle soup. People come from all over Pandaria just to try a taste.", objectives = "Queue for a shift at the Halfhill noodle stand, then complete the bonus objective.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33359] = { id = 33359, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet Us at Starfall Outpost", description = "The archmage has uncovered a potential Shadow Council presence in the valley. He asked me to let you know.\n\nAs soon as you can, join us at Starfall Outpost. We're going to need your muscle to root them out, commander.", completion = "Hello again, {name}. You're just in time.\n\nWe've tracked the Shadow Council to a nearby village. I suspect that Gul'dan is with them.", objectives = "Speak with Archmage Khadgar at Starfall Outpost.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
