quests[33372] = { id = 33372, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "5.4 Raid - RRP - Boss 13 Legendary Quest" }
quests[33373] = { id = 33373, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "5.4 Raid - RRP - Boss 14 Legendary Quest" }
quests[33374] = { id = 33374, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Path of the Mistwalker", description = "You have heard the words of the celestials, but what did you learn on your path to the shrines?\n\nThe wisdom of the pilgrimage is in its silence and simplicity. As you listen to the wind rustling in the trees, and note even the smallest butterfly, your mind is open to learning the deepest lessons the trials have to teach us. Perhaps you noticed the many great beasts that roam the island?\n\nTherein lies your trial. You have learned much from Pandaria, now let us put your knowledge to the test.", progress = "Have the lessons of Pandaria aided you in your journey?", completion = "Let this be your daily lesson, and let it hone your strength, wisdom, and fortitude.", objectives = "Defeat 20 Elite creatures on the Timeless Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33375] = { id = 33375, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Refining The Vision", description = "I have finished grinding the stones, and have attuned the hourglass to a new series of timeways. Will you return to the Siege of Orgrimmar and turn the hourglass once more?\n\nReturn quickly, I am most curious.", progress = "Did you use the Vision of Time? What was the result?", completion = "A tale of true heroism, and a powerful moment in history. But not quite what we are after, I am afraid.\n\nNot much time remains - I shall double my efforts.", objectives = "Use the Vision of Time in the Siege of Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33376] = { id = 33376, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seeking Fate", description = "I have not been completely forthright with you, despite all that you have done to aid the Timewalkers. I cannot tell you everything, not yet, but know this - there is a traitor amongst us. Tell no one of your mission today, and take caution around any of my flight while you hold the Vision of Time.\n\nQuickly now, return to the Siege of Orgrimmar once more and use the hourglass.\n\nAnd be safe.", progress = "Did you use the Vision of Time? What was the result?", completion = "Was that... me? How very interesting.\n\nNow we are beginning to see the shadows between worlds. Was this the future of our world, or simply one possibility? Regardless, our newfound ability to see more deeply into the timeways will allow us to push forward towards the answers we seek.\n\nAllow me some time to continue my research. And be vigilant, hero, for the timeways are as infinite as our enemies.", objectives = "Use the Vision of Time in the Siege of Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33377] = { id = 33377, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hidden Threads", description = "You have kept our mission a secret, and for that I thank you. Knowledge of the timeways, when in the wrong hands, can cause catastrophic devastation. My flight has little power to repair it, now. We must be careful.\n\nThe hourglass grows in power. I believe it can now be used to see much further than before. I wish you to push it to its limits.\n\nReturn to the Siege of Orgrimmar, and focus the hourglass on the most devastating timeway you can find.", completion = "Stormwind... destroyed?\n\nI realize that this vision may come as a shock to you. I know little more than you at this time. I will do my best to search for answers, you have my word.", objectives = "Use the Vision of Time in the Siege of Orgrimmar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33378] = { id = 33378, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Courting Destiny", description = "The Vision of Time is nearly perfected, we now have much more control over the visions we seek. Your efforts have been instrumental in completing the artifact and restoring the strength of not only my flight, but also our allies in the Timewalkers. All of us are in your debt.\n\nQuite fortunately, I have located a sort of crux in time - an intersection of timeways - right here in Pandaria. Take the Vision of Time to the Temple of the White Tiger. There, in the cellars, turn the hourglass.", progress = "Did you use the Vision of Time? What was the result?", completion = "Ah, it seems that our little prince has a role to play yet. We should not speak further of this, lest we alter the future ourselves.\n\nThe woods have ears, hero. Keep silent, we will find our answers in time.", objectives = "Use the Vision of Time at the Temple of the White Tiger in Kun-Lai Summit.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33379] = { id = 33379, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "One Final Turn", description = "I do not wish to ask this of you again, but I do not know who I can trust any longer. I have been using the Vision of Time to gather information, and in my searches, I believe I have found another crux in time. It is in the Caverns of Time itself.\n\nI did not want to believe it when the vision first came to me, but I cannot sit idly by and let this information pass. The Caverns of Time - you must go there, now, and use the Vision of Time.\n\nMove quickly!", completion = "Soridormi, the prime consort of Nozdormu, dead? And I was there as well?\n\nWe cannot know what this means, or what will come to pass, or even if this vision takes place in our timeway. You must speak of this vision to no one, lest we alter the course of time and cause great danger to us all. All we can do now is complete the Vision of Time - it will show us what the future truly holds.", objectives = "Use the Vision of Time in the Caverns of Time in Tanaris.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33380] = { id = 33380, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE", description = "My brother Ga'nar led an assault into the citadel a few hours ago with some of my best lieutenants. They have yet to return.\n\nI need you to move ahead of the pack and find them. We need every warrior we can if we are to stand atop the ogre king's skull by the day's end.", objectives = "Find Ga'nar and 2 Frostwolf Lieutenants at the Ogre Fortress.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33381] = { id = 33381, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Death of a Tyrant", description = "It is good to see you survived the assault. The fortress is nearly ours!\n\nGa'nar and Durotan cleared the way to Gorr'thog's chamber while you were freeing our wolves. Korga and I will make sure no ogres follow you up.\n\n{name}, Gorr'thog is a mighty warrior. Hurry to them before it is too late!", objectives = "Defeat Gorr'thog in Bladespire Citadel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33382] = { id = 33382, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest: Saw Maraad Storm Off" }
