quests[33395] = { id = 33395, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Speak to Thrall", description = "Thrall has a plan for you to take out the catapults preventing us from gaining ground on the battlefield. Speak with him.", sourceObjective = "Speak with Thrall.", sourceObjectiveStatus = "unverified-source-field" }
quests[33398] = { id = 33398, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "South Sprint Practice", description = "For this challenge, run through the arch, then get to the red marker, the purple  marker, then return here.\n\nYou have all the time you need.", objectives = "Run through the arch, hit the red marker, purple marker, then return to the Ironelf games camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33400] = { id = 33400, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "General Problems", description = "My forces are spread thin. The Iron Horde batters our defenses endlessly.\n\nIf you really want to help, find my commanders on the front and help them hold the line.", sourceObjective = "Speak to Commander Dorgosh.", sourceObjectiveStatus = "unverified-source-field" }
quests[33401] = { id = 33401, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Torg's Trouble", description = "My forces are spread thin. The Iron Horde batters our defenses endlessly.\n\nIf you really want to help, find my commanders on the front and help them hold the line.", sourceObjective = "Speak to Commander Torg.", sourceObjectiveStatus = "unverified-source-field" }
quests[33402] = { id = 33402, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verick's Vindicators", description = "My forces are spread thin. The Iron Horde batters our defenses endlessly.\n\nIf you really want to help, find my commanders on the front and help them hold the line.", sourceObjective = "Speak to Commander Verick.", sourceObjectiveStatus = "unverified-source-field" }
quests[33407] = { id = 33407, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE", description = "My brother Ga'nar led an assault into the citadel a few hours ago with some of my best lieutenants. They have yet to return.\n\nI need you to move ahead of the pack and find them. We need every warrior we can if we are to stand atop the Bladespire Lord Gorr'thog's skull by the day's end.", objectives = "Find Ga'nar, Ligra, and Korga at the Ogre Fortress.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33408] = { id = 33408, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Great Balls of Fire!", description = "Ga'nar led Ligra and the others to the second level of the fortress. Your friend, Thrall, also went to lend his skills.\n\nFollow the ramp on the south end of the ramparts outside to join them.\n\nHelp them bring victory to the Frostwolf Clan!", progress = "Yes, traveler?", completion = "Many were killed or wounded on their way here.", objectives = "Speak to Thrall in Bladespire Citadel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33409] = { id = 33409, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elwynn Run", description = "Welcome to the Ironelf games! For this challenge: get to the blue marker, then the green marker, then return here.\n\nScore is based on your time, so get back as fast as you can!", objectives = "Hit the blue marker, then the green marker, then return to the Ironelf games camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33410] = { id = 33410, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Butcher of Bladespire", description = "After Ga'nar advanced into the fortress, the Bladespire unleashed a giant creature on our forces.\n\nI am still weak after using my magic, but at least I can help this orc in her recovery.\n\nHelp take Dorogg down, {name}.", progress = "Have Dorogg fallen?", completion = "This room shook when the monster fell. Your deeds shall not go unremembered.", objectives = "Slay Dorogg the Ruthless.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33412] = { id = 33412, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mopping Up", description = "We've won the day, but our work here is far from finished.\n\nFrostwolves will scour the citadel and root out any survivors. To you, I offer the glory of cleansing the gladiator pits to the north.\n\nAs we launched our attack, we dispatched one of our best to recon that area. If you still thirst for blood, join her there. There's surely some sport left.", completion = "<Igrimar winces as you show her Durotan's orders.>\n\nDon't look at me like that... ungh... I've survived worse.", objectives = "Speak with Igrimar the Resolute at the Circle of Blood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33416] = { id = 33416, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "South Sprint 12", description = "For this challenge, run through the arch, then get to the red marker, the purple  marker, then return here before the bell tolls 12 times. Good luck!", objectives = "Run through the arch, hit the red marker, then the purple, then return to the Ironelf games camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33418] = { id = 33418, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest - Failed" }
quests[33419] = { id = 33419, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Matter of Life and Death", description = "Stranger, please help me!\n\nMy companions and I ventured here to seek the bounty on a monstrous wasp queen.\n\nAfter we set up camp down the hill, we fell asleep. We were attacked in the middle of the night by these horrid, pale... things!\n\nI don't know where my friends have gone, but I heard screams from further down the cavern.\n\nPlease, find my companions. I can't leave here without them!", progress = "They told us not to come out here, but we didn't listen. Why didn't we listen!?", completion = "My prayers have been answered, hero. I will tell everyone back at the village of your deeds.", objectives = "Find Arekk, Diaani, and Zuulo in Bloodthorn Cave.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33422] = { id = 33422, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elwynn Long Distance Practice", description = "For this challenge: run through the arch, then get to the blue marker, the green marker, and finally return here.\n\nYou have all the time you need.", objectives = "Run through the arch, hit the blue marker, then the green marker, then return to the Irongnome games camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33424] = { id = 33424, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Northshire Dash 12", description = "For this challenge: run through the arch, then get to the blue marker and return here as fast as you can.\n\nGet back before you hear the bell toll 12 times.", objectives = "Run through the arch, hit the blue marker, then return to the Ironelf games camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33425] = { id = 33425, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blue/Yellow Sprint 15 INTERNAL REPEATABLE", description = "Ready for a tougher challenge? This one has an extra leg:\n\nRun through the arch...\nGet to the blue marker...\nGet to the green marker...\nthen return here before the bell tolls 15 times.\n\nGood luck!", objectives = "Run through the arch, hit the blue marker, then the green marker, then return to the Ironelf games camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33427] = { id = 33427, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ours is the Fury", description = "Drek'Thar will be fine, once he adjusts. The vision the elemental has bestowed upon him is powerful, and he is on the path of becoming this world's greatest shaman.\n\nYou may wish to inform Warmaster Zog in your garrison of what has transpired here.\n\nHe should be able to deploy some of your troops to the area to further secure the area.", completion = "Well done, commander. I shall see what forces we can dispatch to the area for further clean-up.", objectives = "Speak with Warmaster Zog at your Garrison in Frostfire Ridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33429] = { id = 33429, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elwynn Long Distance Trial: 25", description = "For this challenge: run through the arch, then get to the blue marker, the green marker, and finally return here before the bell tolls 25 times.", objectives = "Run through the arch, hit the blue marker, then the green marker, then return to the Ironelf games camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
