quests[33432] = { id = 33432, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Elwynn South Distance Practice", description = "You want to get some practice in?\n\nFor this challenge: run through the arch, then get to the red marker, the purple marker, and finally return here.\n\nYou have all the time you need.", objectives = "Run through the arch, hit the red marker, then the purple marker, then return to the Ironelf games camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33434] = { id = 33434, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Westfall Race 30", description = "Run through the arch...\nGet to the blue marker...\nGet to the green marker...\nthen return here before the bell tolls 15 times.\n\nGood luck!", objectives = "Run through the arch, hit the blue marker, then the green marker, then return to the Ironelf games camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33438] = { id = 33438, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Time-Warped Primalist" }
