quests[33441] = { id = 33441, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thrall Vision" }
quests[33443] = { id = 33443, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Barrier Destroyed" }
quests[33444] = { id = 33444, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eatercology", description = "Drek'Thar thinks the portions of Exurotus consumed by the goren might be worthless. I am not about to step before the fury without at least trying to recover as many of these \"motes\" as possible.\n\nSlay any goren you find at Magnarok and see if you can extract the motes of Frostfire from them.", progress = "Have you had any luck recovering those motes?", completion = "Goren are abominations. They were created to eat the world. Your have done well.", objectives = "Collect 10 Motes of Frostfire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33447] = { id = 33447, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Bladespire Craftsman" }
quests[33448] = { id = 33448, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE" }
quests[33449] = { id = 33449, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Northwestern Medicine", description = "There is an herb which grows in the crevices and crags of Frostfire Ridge, in places where the icy breath of the sky sips the boiling blood of the earth. Thunderlord climbers gather it often, for it has potent healing properties.\n\nLook for stores of these herbs in Thunderfall, and take what you can. Give them to me when next we meet, and they can be used to save lives in Stonefang.", objectives = "Gather 20 Redleaf Herbs from supply bags in Thunderfall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33450] = { id = 33450, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Warlord's Guard", description = "I don't know what you are accustomed to, traveler, but these lands devour the weak. Perhaps Durotan wishes to rid himself of you. We shall see.\n\nYou must kill the Warlord of the Circle of Blood. Do this and the ogres here will be defeated. But first, you must find him.\n\nI have located his bodyguards nearby. Slay them and bring me their heads. With them, we shall lure the Warlord into the open.", progress = "You still draw breath, hmm?\n\nHave you dealt with the warlord's underlings?", completion = "You have done well in this, but do not become proud. This land has dangers far greater than what you have seen here.", objectives = "Gather the Head of Thunk, the Head of Gullok, and the Head of Splorg.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33454] = { id = 33454, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Cure", description = "Cowards! A curse on these wretched meatbags!\n\nThe Bladespire have always taunted the orc clans by taking our wounded as slaves to fight like dogs in their pits.\n\nIn retaliation for our assault they have poisoned their orc prisoners, leaving them to suffer and die an excruciating death.\n\nOnly their geomancers carry the antidote, traveler. Use it to cure the Frostwolf prisoners.", completion = "You have done the Frostwolf Clan a service, traveler. I shall be sure to tell Durotan of your deeds.", objectives = "Cure 5 Frostwolf Gladiators.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[33456] = { id = 33456, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Catapult Vision" }
